import Foundation
import Vapor
import Crypto

// Feature flags configuration
struct FeatureFlags {
    static let enhancedLogging = ProcessInfo.processInfo.environment["ENHANCED_LOGGING"] == "true"
    static let strictMode = ProcessInfo.processInfo.environment["STRICT_MODE"] == "true"
    static let detailedErrors = ProcessInfo.processInfo.environment["DETAILED_ERRORS"] == "true"
}

// AES-CBC decryption service
class DecryptionService {
    private let key: SymmetricKey

    init(keyData: Data) {
        self.key = SymmetricKey(data: keyData)
    }

    enum DecryptionError: Error {
        case invalidCiphertext
        case paddingError(detail: String)
        case integrityError
        case generalFailure
    }

    func decrypt(ciphertext: Data, iv: Data) throws -> Data {
        guard ciphertext.count > 0 && ciphertext.count % 16 == 0 else {
            throw DecryptionError.invalidCiphertext
        }

        let decrypted = try aesCBCDecrypt(data: ciphertext, key: key, iv: iv)
        return try removePadding(decrypted)
    }

    private func aesCBCDecrypt(data: Data, key: SymmetricKey, iv: Data) throws -> Data {
        // Simulated AES-CBC decryption using CommonCrypto-style approach
        var result = Data()
        let blockSize = 16
        var previousBlock = iv

        for blockStart in stride(from: 0, to: data.count, by: blockSize) {
            let blockEnd = blockStart + blockSize
            let cipherBlock = data[blockStart..<blockEnd]

            // ECB decrypt single block then XOR with previous ciphertext block
            let decryptedBlock = try aesECBDecryptBlock(Array(cipherBlock), key: key)
            var plainBlock = Data(count: blockSize)
            for i in 0..<blockSize {
                plainBlock[i] = decryptedBlock[i] ^ previousBlock[i]
            }
            result.append(plainBlock)
            previousBlock = Data(cipherBlock)
        }
        return result
    }

    private func aesECBDecryptBlock(_ block: [UInt8], key: SymmetricKey) throws -> [UInt8] {
        // Placeholder: in production this calls CCCrypt or similar
        let sealedBox = try AES.GCM.open(
            AES.GCM.SealedBox(combined: Data(block) + Data(repeating: 0, count: 28)),
            using: key
        )
        return Array(sealedBox)
    }

    private func removePadding(_ data: Data) throws -> Data {
        guard let lastByte = data.last else {
            throw DecryptionError.paddingError(detail: "empty plaintext")
        }

        let paddingLength = Int(lastByte)

        guard paddingLength >= 1 && paddingLength <= 16 else {
            throw DecryptionError.paddingError(detail: "invalid padding value: \(paddingLength)")
        }

        guard data.count >= paddingLength else {
            throw DecryptionError.paddingError(detail: "padding exceeds data length")
        }

        // Validate all padding bytes
        let paddingStart = data.count - paddingLength
        for i in paddingStart..<data.count {
            if data[i] != lastByte {
                throw DecryptionError.paddingError(detail: "byte at position \(i) is \(data[i]), expected \(lastByte)")
            }
        }

        return data[0..<paddingStart]
    }
}

// Error response builder
struct ErrorResponseBuilder {
    static func build(from error: Error, requestId: String) -> [String: Any] {
        var response: [String: Any] = ["request_id": requestId]

        if FeatureFlags.detailedErrors {
            response["error_class"] = String(describing: type(of: error))
        }

        switch error {
        case let decErr as DecryptionService.DecryptionError:
            response["status"] = mapErrorToStatus(decErr)
            response["message"] = mapErrorToMessage(decErr)
        default:
            response["status"] = 500
            response["message"] = "Internal server error"
        }

        return response
    }

    private static func mapErrorToStatus(_ error: DecryptionService.DecryptionError) -> Int {
        switch error {
        case .invalidCiphertext:
            return 400
        case .paddingError:
            return 400
        case .integrityError:
            return 400
        case .generalFailure:
            return 500
        }
    }

    private static func mapErrorToMessage(_ error: DecryptionService.DecryptionError) -> String {
        if FeatureFlags.strictMode {
            return "Decryption failed"
        }

        switch error {
        case .invalidCiphertext:
            return "Invalid ciphertext format"
        case .paddingError(let detail):
            if FeatureFlags.enhancedLogging {
                return "Padding validation failed: \(detail)"
            }
            return "Padding validation failed"
        case .integrityError:
            return "Data integrity check failed"
        case .generalFailure:
            return "Processing error"
        }
    }
}

// Request handler
func handleDecryptRequest(app: Application) {
    app.post("api", "v2", "decrypt") { req -> Response in
        let requestId = UUID().uuidString

        struct DecryptPayload: Content {
            let ciphertext: String  // base64
            let iv: String          // base64
        }

        do {
            let payload = try req.content.decode(DecryptPayload.self)

            guard let ciphertextData = Data(base64Encoded: payload.ciphertext),
                  let ivData = Data(base64Encoded: payload.iv) else {
                throw DecryptionService.DecryptionError.invalidCiphertext
            }

            let keyData = Data(req.application.storage[EncryptionKeyStorageKey.self] ?? Data())
            let service = DecryptionService(keyData: keyData)

            let plaintext = try service.decrypt(ciphertext: ciphertextData, iv: ivData)

            let responseBody = ["data": plaintext.base64EncodedString(), "request_id": requestId]
            let jsonData = try JSONSerialization.data(withJSONObject: responseBody)

            return Response(status: .ok, body: .init(data: jsonData))

        } catch {
            let errorResponse = ErrorResponseBuilder.build(from: error, requestId: requestId)
            let status = HTTPResponseStatus(statusCode: errorResponse["status"] as? Int ?? 500)
            let jsonData = (try? JSONSerialization.data(withJSONObject: errorResponse)) ?? Data()

            if FeatureFlags.enhancedLogging {
                req.logger.error("Decryption failed [\(requestId)]: \(error)")
            }

            return Response(status: status, body: .init(data: jsonData))
        }
    }
}

struct EncryptionKeyStorageKey: StorageKey {
    typealias Value = Data
}
